#!/usr/bin/env node
// Hourly single-pin publisher for Pinterest (stdlib only, no npm deps).
// Publishes the pin for the current hourly slot (s00..s10 generated by
// `gen-daily-pin.mjs --batch`) once per day; a `<slug>.published` marker in
// pins/output/daily makes each run idempotent. Exit code is always 0 unless a
// real Pinterest API error occurs, so the scheduled job never fails the run.
//
// Slot mapping (UTC): 11->s00, 12->s01, 14->s02 ... 22->s10
// (13:00 UTC is reserved for the daily blog/calendar job).
//
// Env: PINTEREST_TOKEN, PINTEREST_BOARD_ID, optional PIN_SLOT override.
import fs from 'node:fs';
import path from 'node:path';
import https from 'node:https';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dir = path.join(root, 'pins', 'output', 'daily');
const PINTEREST_API = 'https://api.pinterest.com/v5';

const hour = new Date().getUTCHours();
// On scheduled runs the workflow passes an empty PIN_SLOT, so only use it when
// it actually holds a number (manual dispatch).
const rawSlot = (process.env.PIN_SLOT || '').trim();
const slot = rawSlot !== ''
  ? parseInt(rawSlot, 10)
  : (hour <= 12 ? hour - 11 : hour - 12);
if (!Number.isInteger(slot) || slot < 0 || slot > 10) {
  console.log(`pin-hourly: slot ${slot} out of range (no publish window)`);
  process.exit(0);
}

const token = process.env.PINTEREST_TOKEN || '';
const boardEnv = process.env.PINTEREST_BOARD_ID || '';
console.log(`pin-hourly: slot=${slot} token=${token ? token.length + ' chars' : 'MISSING'} board=${boardEnv ? boardEnv : 'auto-discover'}`);
if (!token) {
  console.warn('WARN pin-hourly: PINTEREST_TOKEN missing — skip (no API call)');
  process.exit(0);
}

const request = (method, urlPath, body) => new Promise((resolve, reject) => {
  const data = body == null ? null : JSON.stringify(body);
  const req = https.request(PINTEREST_API + urlPath, {
    method,
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
      'Pinterest-Agent-Version': '2024-04-01',
      ...(data ? { 'Content-Length': Buffer.byteLength(data) } : {}),
    },
  }, (res) => {
    let raw = '';
    res.on('data', (c) => { raw += c; });
    res.on('end', () => resolve({ status: res.statusCode, body: raw }));
  });
  req.on('error', reject);
  req.setTimeout(30000, () => { req.destroy(new Error('timeout')); });
  if (data) req.write(data);
  req.end();
});
const postJson = (urlPath, body) => request('POST', urlPath, body);
const getJson = (urlPath) => request('GET', urlPath, null);

// PINTEREST_BOARD_ID is optional: discover the board from the account so the
// pipeline needs only one secret. PINTEREST_BOARD_NAME picks a board by name.
async function resolveBoard() {
  if (boardEnv) return boardEnv;
  const want = (process.env.PINTEREST_BOARD_NAME || '').toLowerCase();
  const res = await getJson('/boards?page_size=100');
  if (res.status < 200 || res.status >= 300) {
    console.error(`pin-hourly: cannot list boards — Pinterest API ${res.status}: ${String(res.body).slice(0, 200)}`);
    return null;
  }
  let items = [];
  try { items = JSON.parse(res.body).items || []; } catch { /* ignore */ }
  if (!items.length) {
    console.error('pin-hourly: the account has no boards — create one on pinterest.com');
    return null;
  }
  const picked = (want && items.find((b) => String(b.name || '').toLowerCase().includes(want))) || items[0];
  console.log(`pin-hourly: board auto-discovered: ${picked.name} (${picked.privacy}) id=${picked.id}`);
  return picked.id;
}

let target = null;
try {
  const metas = fs.readdirSync(dir).filter((f) => f.endsWith('.json')).map((f) => {
    try { return JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')); } catch { return null; }
  }).filter(Boolean);
  target = metas.find((m) => m && typeof m.slug === 'string'
    && m.slug.startsWith('s' + String(slot).padStart(2, '0') + '-')
    && !fs.existsSync(path.join(dir, m.slug + '.published'))
    && fs.existsSync(path.join(dir, m.slug + '.png')));
} catch (e) {
  console.warn('WARN pin-hourly: cannot read pins dir — ' + (e && e.message ? e.message : e));
  process.exit(0);
}

if (!target) {
  console.log(`pin-hourly: no unpublished pin for slot ${slot} — nothing to do`);
  process.exit(0);
}

const pngB64 = fs.readFileSync(path.join(dir, target.slug + '.png')).toString('base64');
const title = `${target.title} — herramienta gratuita de magia del caos`.slice(0, 100);
const description = `${target.title} — ${target.url}`.slice(0, 500);

(async () => {
  const me = await getJson('/user/account');
  if (me.status === 401 || me.status === 403) {
    console.error(`pin-hourly: token INVALID (${me.status}) — Pinterest API: ${String(me.body).slice(0, 300)}`);
    process.exit(1);
  }
  let username = '?';
  try { username = JSON.parse(me.body).username || '?'; } catch { /* ignore */ }
  console.log(`pin-hourly: token accepted (/user/account ${me.status}, user=${username})`);

  const board = await resolveBoard();
  if (!board) process.exit(1);

  const res = await postJson('/pins', {
    board_id: board,
    title,
    description,
    media_source: { source_type: 'image_base64', cover_image_base64: pngB64, cover_image_content_type: 'image/png' },
  });
  if (res.status >= 200 && res.status < 300) {
    fs.writeFileSync(path.join(dir, target.slug + '.published'), new Date().toISOString());
    console.log(`pin-hourly: published ${target.slug} (slot ${slot}) -> board ${board}`);
    process.exit(0);
  }
  console.error(`pin-hourly: Pinterest API ${res.status}: ${String(res.body).slice(0, 300)}`);
  process.exit(1);
})().catch((e) => { console.error('pin-hourly error: ' + (e && e.message ? e.message : e)); process.exit(1); });
